const CATALOG = {"_note":"Part A (detect) certificate types. Names match the Part B (tracking) app. id = the code handed to Part B. group = where Part B says it's kept. board = suggested for a COBO board by default (customers can change it). aka = other names it goes by (used in Gemini's instructions). looks = how to tell it apart at a glance.","groups":{"post_public":"Post – public","post_employee":"Post – employee area","on_request":"On premises – on request","on_file":"On file"},"types":[{"id":"sales_tax_permit","name":"Sales tax permit","group":"post_public","board":true,"aka":["seller's permit","sales and use tax permit","certificate of authority","retail sales tax license","vendor's license"],"looks":"Issued by a state department of revenue / taxation / comptroller. Plain form-style certificate with an account or permit number."},{"id":"liquor_license","name":"Liquor license","group":"post_public","board":true,"aka":["ABC license","alcoholic beverage license","alcoholic beverage permit","beer and wine permit","retail liquor permit","on-premises consumption license"],"looks":"Issued by a state alcohol / ABC / liquor control board. Often mentions beer, wine, spirits, malt beverages or on-premises consumption."},{"id":"food_service_permit","name":"Food service establishment permit","group":"post_public","board":true,"aka":["health permit","food establishment permit","food service permit","retail food permit","permit to operate","food establishment license"],"looks":"Issued by a county or city health department. Text-heavy certificate with the establishment name, a permit number and dates. Not a big letter grade."},{"id":"health_grade_card","name":"Health inspection grade card","group":"post_public","board":true,"aka":["sanitation grade card","letter grade placard","inspection score card","food safety rating placard","inspection result placard"],"looks":"Dominated by one large letter grade (A, B, C) or numeric score, or a colored pass/conditional/closed placard, made to be read from across the room. Little body text."},{"id":"business_license","name":"City business license","group":"post_public","board":true,"aka":["business tax certificate","business tax receipt","occupational license","business registration certificate","local business license"],"looks":"Issued by a city or county (finance, licensing or tax office). Lists business name, address, license number, often a fiscal year."},{"id":"certificate_of_occupancy","name":"Certificate of occupancy","group":"post_public","board":true,"aka":["CO","certificate of use","use and occupancy certificate"],"looks":"Issued by a building / inspections department. Heading 'Certificate of Occupancy'; lists use group, construction type, sometimes occupant load. Full certificate, not a small placard."},{"id":"max_occupancy_placard","name":"Maximum occupancy placard","group":"post_public","board":false,"aka":["occupant load sign","maximum capacity sign","occupancy not to exceed placard"],"looks":"Small sign or placard dominated by one big number of persons ('Occupancy not to exceed 120'), usually from the fire marshal. Little other text."},{"id":"fire_operational_permit","name":"Fire operational permit","group":"post_public","board":true,"aka":["fire department permit","fire code permit","assembly permit","fire prevention permit","place of assembly permit"],"looks":"Issued by a fire department / fire marshal / fire prevention bureau as a permit to operate. Not an extinguisher tag or a sprinkler report."},{"id":"no_smoking_sign","name":"No-smoking signage","group":"post_public","board":false,"aka":["no smoking sign","smoke-free sign"],"looks":"A sign with the no-smoking symbol (crossed-out cigarette) and short text."},{"id":"federal_labor_poster","name":"Federal labor law poster (FLSA, EEO, OSHA)","group":"post_employee","board":true,"aka":["federal minimum wage poster","Know Your Rights poster","Job Safety and Health: It's the Law","EEOC poster","all-in-one labor law poster"],"looks":"Large poster (often laminated) packed with many boxed notices. US Department of Labor / EEOC / OSHA logos."},{"id":"osha_300a","name":"OSHA Form 300A injury summary","group":"post_employee","board":true,"aka":["Form 300A","Summary of Work-Related Injuries and Illnesses"],"looks":"A US government form titled 'Summary of Work-Related Injuries and Illnesses', with number boxes and an OSHA header."},{"id":"state_labor_posters","name":"State labor law posters","group":"post_employee","board":true,"aka":["state employment law poster","state all-in-one labor poster"],"looks":"Large poster of boxed notices from a state department of labor / workforce agency (state name and seal)."},{"id":"state_min_wage","name":"State minimum wage notice","group":"post_employee","board":true,"aka":["minimum wage poster","state wage and hour notice"],"looks":"A notice headed with the state's minimum wage and hourly rates. Often one box on an all-in-one state poster."},{"id":"workers_comp_notice","name":"Workers' compensation coverage notice","group":"post_employee","board":true,"aka":["notice of workers' compensation coverage","workers' comp poster","notice to employees"],"looks":"Names the workers' compensation insurance carrier and policy for employees. Often one box on an all-in-one state poster."},{"id":"handwashing_sign","name":"Handwashing signage at sinks","group":"post_employee","board":false,"aka":["employees must wash hands sign","wash your hands sign"],"looks":"Small sign with a handwashing picture and 'Employees must wash hands' style text."},{"id":"food_manager_cert","name":"Certified food protection manager certificate","group":"on_request","board":true,"aka":["ServSafe Manager","food protection manager certification","CFPM","NRFSP","Prometric food safety manager","Learn2Serve manager"],"looks":"A person's certificate (their name in large type) from ServSafe / NRFSP / Prometric / a state, often with a seal. About letter size, not wallet size."},{"id":"food_handler_cards","name":"Food handler cards (all staff)","group":"on_request","board":false,"aka":["food handler card","food handler certificate","ServSafe Food Handler"],"looks":"Wallet or ID-card size cards (or small certificates), one per employee, often several together."},{"id":"hood_suppression_tag","name":"Hood suppression system service tag","group":"on_request","board":false,"aka":["kitchen hood fire suppression tag","Ansul tag","hood system inspection tag"],"looks":"Small hang tag with punched month/year boxes, from a fire protection company. Normally hangs on the kitchen hood."},{"id":"fire_extinguisher_inspection","name":"Fire extinguisher annual inspection","group":"on_request","board":false,"aka":["extinguisher inspection tag","extinguisher service tag","portable extinguisher inspection report"],"looks":"Small punched tag (usually on the extinguisher) or a service company's inspection report listing extinguishers."},{"id":"pest_control_report","name":"Pest control service report","group":"on_request","board":false,"aka":["pest control service ticket","exterminator report","pest control invoice"],"looks":"A service ticket / report on a pest control company's letterhead, with treatment details."},{"id":"irs_ein_letter","name":"IRS employer identification letter","group":"on_file","board":false,"aka":["EIN letter","CP 575","147C letter"],"looks":"A letter on Department of the Treasury / Internal Revenue Service letterhead assigning an EIN."},{"id":"exterior_sign_permit","name":"Exterior sign permit","group":"on_file","board":false,"aka":["sign permit","signage permit"],"looks":"Permit from a city planning / zoning / building department for an outdoor sign."},{"id":"sprinkler_inspection","name":"Sprinkler system inspection report","group":"on_file","board":false,"aka":["fire sprinkler inspection","NFPA 25 inspection report"],"looks":"Multi-line inspection report or tag from a fire sprinkler company."},{"id":"grease_trap_permit","name":"Grease trap / FOG permit","group":"on_file","board":false,"aka":["FOG permit","fats oils and grease permit","grease interceptor permit","wastewater discharge permit"],"looks":"Permit from a water / sewer / wastewater utility mentioning grease trap, interceptor or FOG."},{"id":"backflow_test_cert","name":"Backflow prevention test certificate","group":"on_file","board":false,"aka":["backflow test report","cross-connection test report"],"looks":"Test report form for a backflow prevention assembly (device serial, test results) from a certified tester or water utility."},{"id":"certificate_of_insurance","name":"Certificate of insurance","group":"on_file","board":false,"aka":["COI","ACORD 25","certificate of liability insurance"],"looks":"Usually the ACORD 25 'Certificate of Liability Insurance' form: dense grid of policies and limits."},{"id":"alarm_permit","name":"Alarm system permit","group":"on_file","board":false,"aka":["alarm registration","burglar alarm permit","false alarm permit"],"looks":"Permit or registration from a police department or city for a security / burglar alarm."}],"other":{"id":"other","name":"Other / not sure","board":true}};

// Part A "detect", the Gemini request itself. Shared by:
//   tools/gemini-detect.js   (the local preview server: reads the key from .gemini-key)
//   worker/worker.js         (the Cloudflare Worker, built by tools/build-worker.js: the key is a Worker secret)
// Plain JavaScript with no Node-only code, so it can run in both. Edit it here, then rebuild the Worker.
//
// makeDetector(catalog, { model, thinking, endpoint }) -> { detect(key, image, mime, opts), CHOICES }
//   catalog = the parsed data/cert-types.json
//   detect() resolves { items, photo_notes, model, settings, usage, ms } or throws an Error with .code
//   (no-key, rate-limit, timeout, network, gemini, bad-json).
function makeDetector(CATALOG, cfg) {
  const ENDPOINT = cfg.endpoint || 'https://generativelanguage.googleapis.com/v1beta/interactions';
  const ISSUES = ['none', 'glare', 'too_small', 'blurry', 'cut_off', 'blocked'];
  const IDS = [...CATALOG.types.map(t => t.id), CATALOG.other.id];

  const INSTRUCTIONS = `You look at a photo of a wall in a restaurant or other business (or of documents laid out on a table or other
surface) and find every compliance document in it:
permits, licenses, certificates, inspection cards, required posters, notices, compliance signs and tags.

For each one, return:
- box_2d: [ymin, xmin, ymax, xmax] around the document's outer edge (including its frame, if framed), normalized to 0-1000.
- paper_2d: the same, but around the paper itself, inside any frame, mat or sleeve (equal to box_2d if unframed).
- corners: the paper's 4 corners as [y, x] points (0-1000), in the order top-left, top-right, bottom-right,
  bottom-left as seen in the photo. Put them exactly on the paper's own corners (inside any frame), following its real
  edges when it is tilted or photographed at an angle.
- types: the matching type id(s) from the catalog below. Use one id, unless it is an all-in-one poster that combines
  several notices (then list every notice it covers). Use "other" if it is a compliance document you can't match.
- heading: the largest title text you can read on it, as written ("" if unreadable).
- issuer: the agency or company that issued it, if you can read it at a glance ("" if not).
- confidence: "high" if the heading or design clearly identifies the type, "medium" if it is a strong guess from the
  layout, seal or partial text, "low" if you are unsure.
- reason: a few words on what gave it away (e.g. "big A grade", "ACORD 25 grid", "ABC board seal").
- closer_photo: "none" if its heading and seal are easy to read in this photo. Otherwise why a closer photo of just
  this one would help: "glare" (reflection hides part of it), "too_small" (too far away to read), "blurry",
  "cut_off" (partly outside the photo) or "blocked" (something in front of it).

Rules:
- Identify the TYPE only. Do not read or report dates, license numbers, names or other fine print.
- Local names differ by state and city; match on meaning (the "also called" lists help). Never invent a new type id.
- Skip things that are not compliance documents: menus, art, photos, mirrors, windows, clocks, decorations, light
  switches, outlets. Include a paper document you can't identify as "other" with low confidence.
- One box per physical item. Several documents in one frame each get their own box. Several small wallet cards in one
  sleeve can share one box.
- Watch the look-alikes: a health inspection grade card (one big grade or score) vs a food service establishment permit
  (text-heavy certificate); a maximum occupancy placard (one big number) vs a certificate of occupancy (full
  certificate); a food protection manager certificate (letter size, a person's name) vs food handler cards (wallet
  size); a fire operational permit vs fire extinguisher or sprinkler inspection paperwork.
- If the photo is blurry, too far away or has glare, still return what you can and say so in photo_notes.
- location: where the business is, if the documents show it (an issuing state agency, a state seal, a county or city
  name). state = its 2-letter US postal code (e.g. "NC"); county and city if shown; evidence = which document showed it
  (e.g. "liquor license"). Use "" for anything not shown. Don't guess from the style of the room.

Catalog (id: name. Also called ... Looks: ...):
${CATALOG.types.map(t => `- ${t.id}: ${t.name}. Also called: ${t.aka.join('; ')}. Looks: ${t.looks}`).join('\n')}
- other: a compliance document that matches none of the above.`;

  const SCHEMA = {
    type: 'object',
    properties: {
      items: {
        type: 'array',
        items: {
          type: 'object',
          properties: {
            box_2d: { type: 'array', items: { type: 'integer', minimum: 0, maximum: 1000 }, minItems: 4, maxItems: 4 },
            paper_2d: { type: 'array', items: { type: 'integer', minimum: 0, maximum: 1000 }, minItems: 4, maxItems: 4 },
            corners: { type: 'array', minItems: 4, maxItems: 4, items: { type: 'array', items: { type: 'integer', minimum: 0, maximum: 1000 }, minItems: 2, maxItems: 2 } },
            types: { type: 'array', items: { type: 'string', enum: IDS }, minItems: 1, maxItems: 8 },
            heading: { type: 'string' },
            issuer: { type: 'string' },
            confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
            reason: { type: 'string' },
            closer_photo: { type: 'string', enum: ISSUES },
          },
          required: ['box_2d', 'paper_2d', 'corners', 'types', 'heading', 'confidence', 'closer_photo'],
        },
      },
      photo_notes: { type: 'string' },
      location: {
        type: 'object',
        properties: { state: { type: 'string' }, county: { type: 'string' }, city: { type: 'string' }, evidence: { type: 'string' } },
        required: ['state'],
      },
    },
    required: ['items'],
  };

  // The lab can try other settings per photo (speed vs accuracy). Only these values are accepted.
  const CHOICES = {
    model: ['gemini-3.8-flash', 'gemini-3.6-flash', 'gemini-3.5-flash-lite'],
    thinking: ['minimal', 'low', 'medium', 'high'],
    resolution: ['low', 'medium', 'high', 'ultra_high'],
  };
  const pick = (k, v, dflt) => (CHOICES[k].includes(v) ? v : dflt);
  const clamp = (b) => b.map(n => Math.max(0, Math.min(1000, Math.round(n))));

  // the model's final text: steps[].content[] of type "text" (output_text when the API provides it)
  function outputText(body) {
    if (typeof body.output_text === 'string') return body.output_text;
    const texts = [];
    for (const s of body.steps || body.outputs || []) {
      if (s.type && s.type !== 'model_output') continue;
      for (const c of Array.isArray(s.content) ? s.content : [s]) if (c?.type === 'text' && c.text) texts.push(c.text);
    }
    return texts.join('');
  }

  // image: base64 JPEG/PNG/WebP (no "data:" prefix). opts: { model, thinking, resolution } (lab testing only).
  async function detect(key, image, mime = 'image/jpeg', opts = {}) {
    if (!key) { const e = new Error('No Gemini API key yet.'); e.code = 'no-key'; throw e; }
    const settings = { model: pick('model', opts.model, cfg.model), thinking: pick('thinking', opts.thinking, cfg.thinking), resolution: pick('resolution', opts.resolution, 'high') };
    const t0 = Date.now();
    const res = await fetch(ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-goog-api-key': key },
      body: JSON.stringify({
        model: settings.model,
        store: false,                                   // don't keep customer photos on Google's side
        system_instruction: INSTRUCTIONS,
        input: [
          { type: 'text', text: 'Find the compliance documents in this photo. Return JSON only.' },
          { type: 'image', mime_type: mime, data: image, resolution: settings.resolution },
        ],
        generation_config: { thinking_level: settings.thinking },
        response_format: { type: 'text', mime_type: 'application/json', schema: SCHEMA },
      }),
      signal: AbortSignal.timeout(90000),
    }).catch((err) => {
      const e = new Error(err.name === 'TimeoutError' ? 'Gemini took longer than 90 seconds. Try again.' : `Couldn't reach Gemini (${err.message}).`);
      e.code = err.name === 'TimeoutError' ? 'timeout' : 'network'; throw e;
    });
    const body = await res.json().catch(() => ({}));
    if (!res.ok || body.status === 'failed') {
      const msg = body.error?.message || body.errors?.[0]?.message || `Gemini error ${res.status}`;
      const e = new Error(msg); e.code = res.status === 429 ? 'rate-limit' : 'gemini'; e.status = res.status; throw e;
    }
    const text = outputText(body);
    let out;
    try { out = JSON.parse(text.replace(/^```(?:json)?\s*|\s*```$/g, '')); }
    catch { const e = new Error('Gemini sent back something that isn\'t JSON.'); e.code = 'bad-json'; e.raw = text.slice(0, 2000); throw e; }
    // keep only well-formed items and known types (the schema should already ensure this)
    const items = (out.items || []).filter(i => Array.isArray(i.box_2d) && i.box_2d.length === 4).map(i => ({
      box_2d: clamp(i.box_2d), paper_2d: Array.isArray(i.paper_2d) && i.paper_2d.length === 4 ? clamp(i.paper_2d) : clamp(i.box_2d),
      corners: Array.isArray(i.corners) && i.corners.length === 4 && i.corners.every(p => Array.isArray(p) && p.length === 2) ? i.corners.map(clamp) : null,
      types: [...new Set((i.types || []).filter(t => IDS.includes(t)))].slice(0, 8),
      heading: String(i.heading || ''), issuer: String(i.issuer || ''),
      confidence: ['high', 'medium', 'low'].includes(i.confidence) ? i.confidence : 'low', reason: String(i.reason || ''),
      closer_photo: ISSUES.includes(i.closer_photo) ? i.closer_photo : 'none',
    })).map(i => (i.types.length ? i : { ...i, types: ['other'], confidence: 'low' }));
    const L = out.location || {}, st = String(L.state || '').trim().toUpperCase();
    const location = { state: /^[A-Z]{2}$/.test(st) ? st : '', county: String(L.county || ''), city: String(L.city || ''), evidence: String(L.evidence || '') };
    return { items, photo_notes: String(out.photo_notes || ''), location, model: body.model || settings.model, settings, usage: body.usage || null, ms: Date.now() - t0 };
  }

  return { detect, CHOICES };
}

// The Cloudflare Worker's own part: who may call it, size limits, an optional daily cap, then the Gemini request.
// tools/build-worker.js puts the catalog + tools/detect-core.js + this file together into worker/worker.js.
// Settings (all optional except the secret), set in the Worker's Settings -> Variables and Secrets:
//   GEMINI_API_KEY   (secret, required)  the Google AI Studio key
//   ALLOWED_ORIGINS  (text)              extra sites allowed to call it, comma separated, e.g. https://www.complianceboards.com
//   ALLOW_LOCALHOST  (text)              "1" lets pages on localhost call it (testing only)
//   DAILY_LIMIT      (text)              photos per day; default 300. Only counted if a KV namespace named LIMITS is bound.
const DEFAULT_ORIGINS = ['https://jcolli40.github.io', 'https://www.complianceboards.com', 'https://complianceboards.com'];
const MIMES = ['image/jpeg', 'image/png', 'image/webp'];
const MAX_BYTES = 6e6;                                   // the page sends a ~1600 px JPEG, about 0.3 to 1 MB

const detector = makeDetector(CATALOG, { model: 'gemini-3.6-flash', thinking: 'low' });

function originAllowed(origin, env) {
  if (!origin) return false;
  const list = [...DEFAULT_ORIGINS, ...String(env.ALLOWED_ORIGINS || '').split(',').map(s => s.trim()).filter(Boolean)];
  if (list.includes(origin)) return true;
  return env.ALLOW_LOCALHOST === '1' && /^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(origin);
}

export default {
  async fetch(request, env) {
    const origin = request.headers.get('Origin') || '';
    const ok = originAllowed(origin, env);
    const cors = ok ? { 'Access-Control-Allow-Origin': origin, 'Access-Control-Allow-Methods': 'GET, POST, OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type', 'Access-Control-Max-Age': '86400', Vary: 'Origin' } : {};
    const send = (code, obj) => new Response(JSON.stringify(obj), { status: code, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...cors } });

    if (request.method === 'OPTIONS') return new Response(null, { status: ok ? 204 : 403, headers: cors });
    if (!ok) return send(403, { error: 'This site isn\'t allowed to use the wall reader.', code: 'origin' });
    // (Cloudflare tells us roughly where the visitor is: a fallback guess for "Your business is in")
    const where = { country: request.cf?.country || '', region: request.cf?.country === 'US' ? request.cf?.regionCode || '' : '' };
    if (request.method === 'GET') return send(200, { ready: !!env.GEMINI_API_KEY, model: 'gemini-3.6-flash', ...where });
    if (request.method !== 'POST') return send(405, { error: 'POST a photo' });

    if (Number(request.headers.get('Content-Length') || 0) > MAX_BYTES) return send(413, { error: 'Photo too large', code: 'too-large' });
    let body;
    try { body = JSON.parse(await request.text()); } catch { return send(400, { error: 'Bad request' }); }
    if (typeof body.image !== 'string' || !body.image || body.image.length > MAX_BYTES * 1.4) return send(400, { error: 'No usable photo' });
    const mime = MIMES.includes(body.mime) ? body.mime : 'image/jpeg';

    // optional daily cap, kept in a KV namespace bound as LIMITS (a soft cap: a burst can overshoot it a little)
    if (env.LIMITS) {
      const day = new Date().toISOString().slice(0, 10), key = `day:${day}`, limit = Number(env.DAILY_LIMIT) || 300;
      const used = Number(await env.LIMITS.get(key)) || 0;
      if (used >= limit) return send(429, { error: 'The wall reader has reached its daily limit. Try again tomorrow.', code: 'daily-limit' });
      await env.LIMITS.put(key, String(used + 1), { expirationTtl: 172800 });
    }

    try {
      const out = await detector.detect(env.GEMINI_API_KEY, body.image, mime, {});   // (test settings from the page are ignored here)
      return send(200, out);
    } catch (e) {
      return send(e.code === 'no-key' ? 503 : e.code === 'rate-limit' ? 429 : 502, { error: e.message, code: e.code || 'error' });
    }
  },
};
